// ----------------------
// NORMALIZADOR
// ----------------------

function normalizar(texto) {
  return (texto || "")
    .toString()
    .toLowerCase()
    .normalize("NFD") // separa tildes
    .replace(/[\u0300-\u036f]/g, "") // elimina tildes
    .trim();
}

// ----------------------
// MAPEO DE CIUDADES → ID
// ----------------------

const ciudadesMap = {
  "santa cruz": 1,
  "beni": 2,
  "chuquisaca": 3,
  "cochabamba": 4,
  "la paz": 5,
  "oruro": 6,
  "pando": 7,
  "potosi": 8,
  "tarija": 9,
  "todas": 10
};

// ----------------------
// INPUT CIUDAD
// ----------------------

// viene como string
let ciudadRaw = $('When Executed by Another Workflow').first().json.ciudad || "";

// normalizar
let ciudadNormalizada = normalizar(ciudadRaw);

// obtener ID
let ciudadId = ciudadesMap[ciudadNormalizada] || 10; // default = Todas

// ID de "Todas"
const TODAS_ID = 10;

// ----------------------
// DATA
// ----------------------

let items = $input.first()?.json?.data || [];

if (!Array.isArray(items)) {
  items = [];
}

// ----------------------
// FILTRO
// ----------------------

let filtrados = items.filter(prod => {
  const sucursal = Number(prod.ciudad_producto_sucursal);
  return sucursal === ciudadId || sucursal === TODAS_ID;
});

// ----------------------
// ELIMINAR DUPLICADOS
// ----------------------

let uniqueMap = new Map();

filtrados.forEach(prod => {
  if (!uniqueMap.has(prod.id)) {
    uniqueMap.set(prod.id, prod);
  }
});

let resultado = Array.from(uniqueMap.values());

// ----------------------
// OUTPUT
// ----------------------

return [
  {
    json: {
      ciudad_input: ciudadRaw,
      ciudad_normalizada: ciudadNormalizada,
      ciudad_id: ciudadId,
      total_productos: resultado.length,
      data: resultado
    }
  }
];

// ----------------------
// NORMALIZADOR
// ----------------------

function normalizar(texto) {
  return (texto || "")
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

// ----------------------
// INPUTS
// ----------------------

// ciudad a buscar
let filtroRaw = $('When Executed by Another Workflow').first().json.ciudad || "";

// normalizar
let filtro = normalizar(filtroRaw);

// ----------------------
// DATA
// ----------------------

let data = $input.first().json.data  || [];

// si viene como { data: [...] }
if (data.data) {
  data = data.data;
}

// asegurar array
if (!Array.isArray(data)) {
  data = [];
}

// ----------------------
// FILTRO
// ----------------------

let resultado = data.filter(item => {
  let nombre = normalizar(item.name || item.nombre || "");
  return nombre === filtro;
});

// ----------------------
// OUTPUT
// ----------------------

return [
  {
    json: {
      filtro_input: filtroRaw,
      filtro_normalizado: filtro,
      total_encontrados: resultado.length,
      data: resultado
    }
  }
];
